/* ---------------- chico/chica por el nombre (para «Pillo/Pilla», «Serio/Seria») ---------------- */
function generoDe(nom){ const n=String(nom||'').trim().split(/\s+/)[0].normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase();
  const chicas=['carmen','isabel','raquel','pilar','consuelo','rocio','mercedes','dolores','ines','beatriz','luz','paz','sol','nieves','ester','esther','abigail','noemi','miriam','ruth','belen','maribel','mabel','iris','abril','aitana','naiara','irene','nerea','lis','ainhoa','uxue','sabel','alba','nuria','noelia'];
  const chicos=['luca','borja','nicola','joshua','elias','matias','tobias','ezra','noa','iago','santiago','tiago','yago','andrea'];
  if(chicas.indexOf(n)>=0) return 'chica'; if(chicos.indexOf(n)>=0) return 'chico'; return /a$/.test(n)?'chica':'chico'; }
