function coKeyAcc(dn,key){ const L=CO_LET[((dn%7)+7)%7], si=CO_SH.indexOf(L), fi=CO_FL.indexOf(L); return (key.sig>0&&si>=0&&si<key.sig)?1:((key.sig<0&&fi>=0&&fi<-key.sig)?-1:0); }
