    for(let yy=yL4+10;yy<=y+1;yy+=10) sv('line',{x1:cx-13,x2:cx+13,y1:yy,y2:yy,stroke:col,'stroke-width':1.6},g);
    const h=coGlyph(g,hueca?'noteheadWhole':'noteheadBlack',cx,y,col);
