  let dedoA=null;
  const zonaOrd=ev=>{ const p=punto(ev); if(p.x<A.xL-6||p.x>A.xR+6) return null; const dn=dnM-Math.round((p.y-yM)/5); if(Math.abs(dn-dnM)>9) return null; return {ord:true,dn}; };
